static int read_env_passwd(unsigned char *sum, size_t length) /* <=== read_env_passwd */ 
{
	int fd;
	int ret = 0;
	unsigned char c;

	if (!sum && length < 1)
		return -EINVAL;

	fd = open(PASSWD_FILE, O_RDONLY);

	if (fd < 0)
		return fd;

	do {
		ret = read(fd, &c, sizeof(char));

		if (ret < 0)
			goto exit;

		*sum = to_digit(c) << 4;

		ret = read(fd, &c, sizeof(char));

		if (ret < 0)
			goto exit;

		*sum |= to_digit(c);
		sum++;
		length--;
	} while(length > 0);

exit:

	ret = 0;

	close(fd);

	return ret;
}

void digest_free(struct digest *d) /* <=== digest_free */ 
{
	if (!d)
		return;
	d->algo->free(d);
	free(d->ctx);
	free(d);
}

static void malloc_extend_top(INTERNAL_SIZE_T nb) /* <=== malloc_extend_top */ 
{
	char *brk;		/* return value from sbrk */
	INTERNAL_SIZE_T front_misalign;	/* unusable bytes at front of sbrked space */
	INTERNAL_SIZE_T correction;	/* bytes for 2nd sbrk call */
	char *new_brk;		/* return of 2nd sbrk call */
	INTERNAL_SIZE_T top_size;	/* new size of top chunk */

	mchunkptr old_top = top;	/* Record state of old top */
	INTERNAL_SIZE_T old_top_size = chunksize(old_top);
	char *old_end = (char *) (chunk_at_offset(old_top, old_top_size));

	/* Pad request with top_pad plus minimal overhead */

	INTERNAL_SIZE_T sbrk_size = nb + top_pad + MINSIZE;
	unsigned long pagesz = malloc_getpagesize;

	/* If not the first time through, round to preserve page boundary */
	/* Otherwise, we need to correct to a page size below anyway. */
	/* (We also correct below if an intervening foreign sbrk call.) */

	if (sbrk_base != (char*)(-1))
		sbrk_size = (sbrk_size + (pagesz - 1)) & ~(pagesz - 1);

	brk = (char*)(sbrk(sbrk_size));

	/* Fail if sbrk failed or if a foreign sbrk call killed our space */
	if (brk == (char*)(NULL) || (brk < old_end && old_top != initial_top))
		return;

	sbrked_mem += sbrk_size;

	if (brk == old_end) {	/* can just add bytes to current top */
		top_size = sbrk_size + old_top_size;
		set_head (top, top_size | PREV_INUSE);
	} else {
		if (sbrk_base == (char*)(-1))	/* First time through. Record base */
			sbrk_base = brk;
		else		/* Someone else called sbrk().  Count those bytes as sbrked_mem. */
			sbrked_mem += brk - (char*)old_end;

		/* Guarantee alignment of first new chunk made from this space */
		front_misalign =
			(unsigned long) chunk2mem(brk) & MALLOC_ALIGN_MASK;
		if (front_misalign > 0) {
			correction = (MALLOC_ALIGNMENT) - front_misalign;
			brk += correction;
		} else
			correction = 0;

		/* Guarantee the next brk will be at a page boundary */

		correction += ((((unsigned long) (brk + sbrk_size)) +
				(pagesz - 1)) & ~(pagesz - 1)) -
			((unsigned long) (brk + sbrk_size));

		/* Allocate correction */
		new_brk = (char*) (sbrk(correction));
		if (new_brk == (char*)(NULL))
			return;

		sbrked_mem += correction;

		top = (mchunkptr) brk;
		top_size = new_brk - brk + correction;
		set_head (top, top_size | PREV_INUSE);

		if (old_top != initial_top) {

			/* There must have been an intervening foreign sbrk call. */
			/* A double fencepost is necessary to prevent consolidation */

			/* If not enough space to do this, then user did something very wrong */
			if (old_top_size < MINSIZE) {
				set_head (top, PREV_INUSE);	/* will force null return from malloc */
				return;
			}

			/* Also keep size a multiple of MALLOC_ALIGNMENT */
			old_top_size = (old_top_size -
					3 * SIZE_SZ) & ~MALLOC_ALIGN_MASK;
			set_head_size (old_top, old_top_size);
			chunk_at_offset (old_top, old_top_size)->size =
				SIZE_SZ | PREV_INUSE;
			chunk_at_offset (old_top, old_top_size + SIZE_SZ)->size =
				SIZE_SZ | PREV_INUSE;
			/* If possible, release the rest. */
			if (old_top_size >= MINSIZE)
				free(chunk2mem (old_top));
		}
	}

	if ((unsigned long) sbrked_mem > (unsigned long) max_sbrked_mem)
		max_sbrked_mem = sbrked_mem;
	if ((unsigned long) (mmapped_mem + sbrked_mem) > (unsigned long) max_total_mem)
		max_total_mem = mmapped_mem + sbrked_mem;
}

static int is_passwd_env_enable(void) /* <=== is_passwd_env_enable */ 
{
	int fd;

	fd = open(PASSWD_FILE, O_RDONLY);

	if (fd < 0)
		return 0;

	close(fd);

	return 1;
}

static unsigned char to_digit(unsigned char c) /* <=== to_digit */ 
{
	if (c >= '0' && c <= '9')
		c -= '0';
	else
		c -= 'a' - 10;

	return c;
}

