void free(void *mem) /* <=== free */ 
{
	mchunkptr p;		/* chunk corresponding to mem */
	INTERNAL_SIZE_T hd;	/* its head field */
	INTERNAL_SIZE_T sz;	/* its size */
	int idx;		/* its bin index */
	mchunkptr next;		/* next contiguous chunk */
	INTERNAL_SIZE_T nextsz;	/* its size */
	INTERNAL_SIZE_T prevsz;	/* size of previous contiguous chunk */
	mchunkptr bck;		/* misc temp for linking */
	mchunkptr fwd;		/* misc temp for linking */
	int islr;		/* track whether merging with last_remainder */

	if (!mem)		/* free(0) has no effect */
		return;

	p = mem2chunk(mem);
	hd = p->size;


	sz = hd & ~PREV_INUSE;
	next = chunk_at_offset(p, sz);
	nextsz = chunksize(next);

	if (next == top) { /* merge with top */
		sz += nextsz;

		if (!(hd & PREV_INUSE)) {	/* consolidate backward */
			prevsz = p->prev_size;
			p = chunk_at_offset(p, -((long) prevsz));
			sz += prevsz;
			unlink (p, bck, fwd);
		}

		set_head(p, sz | PREV_INUSE);
		top = p;
#ifdef USE_MALLOC_TRIM
		if ((unsigned long) (sz) >= (unsigned long)trim_threshold)
			malloc_trim(top_pad);
#endif
		return;
	}

	set_head(next, nextsz); /* clear inuse bit */

	islr = 0;

	if (!(hd & PREV_INUSE)) {	/* consolidate backward */
		prevsz = p->prev_size;
		p = chunk_at_offset(p, -((long) prevsz));
		sz += prevsz;

		if (p->fd == last_remainder) /* keep as last_remainder */
			islr = 1;
		else
			unlink(p, bck, fwd);
	}

	if (!(inuse_bit_at_offset(next, nextsz))) { /* consolidate forward */
		sz += nextsz;

		if (!islr && next->fd == last_remainder) { /* re-insert last_remainder */
			islr = 1;
			link_last_remainder(p);
		} else
			unlink(next, bck, fwd);
	}


	set_head(p, sz | PREV_INUSE);
	set_foot(p, sz);
	if (!islr)
		frontlink(p, sz, idx, bck, fwd);
}

static inline int crypto_memneq(const void *a, const void *b, size_t size) /* <=== crypto_memneq */ 
{
	return __crypto_memneq(a, b, size) != 0UL ? 1 : 0;
}

void *calloc(size_t n, size_t elem_size) /* <=== calloc */ 
{
	size_t size = elem_size * n;
	void *r = malloc(size);

	if (!r)
		return r;

	memset(r, 0x0, size);

	return r;
}

