void *calloc(size_t n, size_t elem_size) /* <=== calloc */ 
{
	mchunkptr p;
	INTERNAL_SIZE_T csz;
	INTERNAL_SIZE_T sz = n * elem_size;
	void *mem;

	/* check if expand_top called, in which case don't need to clear */
	mchunkptr oldtop = top;
	INTERNAL_SIZE_T oldtopsize = chunksize(top);

	if ((long)n < 0)
		return NULL;

	mem = malloc(sz);

	if (!mem)
		return NULL;
	else {
		p = mem2chunk(mem);

		/* Two optional cases in which clearing not necessary */
		csz = chunksize(p);

		if (p == oldtop && csz > oldtopsize) {
			/* clear only the bytes from non-freshly-sbrked memory */
			csz = oldtopsize;
		}

		memset(mem, 0, csz - SIZE_SZ);
		return mem;
	}
}

static struct digest_algo *digest_algo_get_by_name(const char *name) /* <=== digest_algo_get_by_name */ 
{
	struct digest_algo *d = NULL;
	struct digest_algo *tmp;
	int priority = -1;

	if (!name)
		return NULL;

	list_for_each_entry(tmp, &digests, list) {
		if (strcmp(tmp->base.name, name) != 0)
			continue;

		if (tmp->base.priority <= priority)
			continue;

		d = tmp;
		priority = tmp->base.priority;
	}

	return d;
}

struct digest *digest_alloc(const char *name) /* <=== digest_alloc */ 
{
	struct digest *d;
	struct digest_algo *algo;

	algo = digest_algo_get_by_name(name);
	if (!algo)
		return NULL;

	d = xzalloc(sizeof(*d));
	d->algo = algo;
	d->ctx = xzalloc(algo->ctx_length);
	if (d->algo->alloc(d)) {
		digest_free(d);
		return NULL;
	}

	return d;
}

void *malloc(size_t bytes) /* <=== malloc */ 
{
	mchunkptr victim;	/* inspected/selected chunk */
	INTERNAL_SIZE_T victim_size;	/* its size */
	int idx;		/* index for bin traversal */
	mbinptr bin;		/* associated bin */
	mchunkptr remainder;	/* remainder from a split */
	long remainder_size;	/* its size */
	int remainder_index;	/* its bin index */
	unsigned long block;	/* block traverser bit */
	int startidx;		/* first bin of a traversed block */
	mchunkptr fwd;		/* misc temp for linking */
	mchunkptr bck;		/* misc temp for linking */
	mbinptr q;		/* misc temp */

	INTERNAL_SIZE_T nb;

	if ((long) bytes < 0)
		return NULL;

	nb = request2size(bytes); /* padded request size; */

	/* Check for exact match in a bin */

	if (is_small_request(nb)) { /* Faster version for small requests */
		idx = smallbin_index(nb);

		/* No traversal or size check necessary for small bins.  */

		q = bin_at(idx);
		victim = last(q);

		/* Also scan the next one, since it would have a remainder < MINSIZE */
		if (victim == q) {
			q = next_bin(q);
			victim = last(q);
		}
		if (victim != q) {
			victim_size = chunksize(victim);
			unlink(victim, bck, fwd);
			set_inuse_bit_at_offset(victim, victim_size);
			return chunk2mem(victim);
		}
		idx += 2;	/* Set for bin scan below. We've already scanned 2 bins. */
	} else {
		idx = bin_index(nb);
		bin = bin_at(idx);

		for (victim = last(bin); victim != bin; victim = victim->bk) {
			victim_size = chunksize(victim);
			remainder_size = victim_size - nb;

			if (remainder_size >= (long)MINSIZE) {	/* too big */
				--idx;	/* adjust to rescan below after checking last remainder */
				break;
			}

			else if (remainder_size >= 0) {	/* exact fit */
				unlink(victim, bck, fwd);
				set_inuse_bit_at_offset(victim, victim_size);
				return chunk2mem(victim);
			}
		}
		++idx;
	}

	/* Try to use the last split-off remainder */

	if ((victim = last_remainder->fd) != last_remainder) {
		victim_size = chunksize(victim);
		remainder_size = victim_size - nb;

		if (remainder_size >= (long)MINSIZE) {	/* re-split */
			remainder = chunk_at_offset(victim, nb);
			set_head(victim, nb | PREV_INUSE);
			link_last_remainder(remainder);
			set_head(remainder, remainder_size | PREV_INUSE);
			set_foot(remainder, remainder_size);
			return chunk2mem(victim);
		}

		clear_last_remainder;

		if (remainder_size >= 0) {	/* exhaust */
			set_inuse_bit_at_offset(victim, victim_size);
			return chunk2mem(victim);
		}
		/* Else place in bin */
		frontlink(victim, victim_size, remainder_index, bck, fwd);
	}

	/*
	   If there are any possibly nonempty big-enough blocks,
	   search for best fitting chunk by scanning bins in blockwidth units.
	 */
	if ((block = idx2binblock (idx)) <= binblocks) {
		/* Get to the first marked block */
		if ((block & binblocks) == 0) {
			/* force to an even block boundary */
			idx = (idx & ~(BINBLOCKWIDTH - 1)) + BINBLOCKWIDTH;
			block <<= 1;
			while ((block & binblocks) == 0) {
				idx += BINBLOCKWIDTH;
				block <<= 1;
			}
		}

		/* For each possibly nonempty block ... */
		for (;;) {
			startidx = idx;	/* (track incomplete blocks) */
			q = bin = bin_at(idx);

			/* For each bin in this block ... */
			do {
				/* Find and use first big enough chunk ... */
				for (victim = last(bin); victim != bin;
				     victim = victim->bk) {
					victim_size = chunksize(victim);
					remainder_size = victim_size - nb;

					if (remainder_size >= (long)MINSIZE) {	/* split */
						remainder =
							chunk_at_offset (victim,
									 nb);
						set_head(victim,
							nb | PREV_INUSE);
						unlink(victim, bck, fwd);
						link_last_remainder(remainder);
						set_head(remainder,
							remainder_size |
							PREV_INUSE);
						set_foot(remainder,
							remainder_size);
						return chunk2mem(victim);
					} else if (remainder_size >= 0) { /* take */
						set_inuse_bit_at_offset(victim,
									victim_size);
						unlink(victim, bck, fwd);
						return chunk2mem(victim);
					}
				}
				bin = next_bin (bin);
			} while ((++idx & (BINBLOCKWIDTH - 1)) != 0);

			/* Clear out the block bit. */
			do {	/* Possibly backtrack to try to clear a partial block */
				if ((startidx & (BINBLOCKWIDTH - 1)) == 0) {
					binblocks &= ~block;
					break;
				}
				--startidx;
				q = prev_bin(q);
			} while (first(q) == q);

			/* Get to the next possibly nonempty block */

			if ((block <<= 1) <= binblocks && (block != 0)) {
				while ((block & binblocks) == 0) {
					idx += BINBLOCKWIDTH;
					block <<= 1;
				}
			} else
				break;
		}
	}

	/* Try to use top chunk */

	/* Require that there be a remainder, ensuring top always exists  */
	if ((remainder_size = chunksize (top) - nb) < (long) MINSIZE) {
		/* Try to extend */
		malloc_extend_top(nb);
		if ((remainder_size = chunksize(top) - nb) < (long) MINSIZE)
			return NULL;	/* propagate failure */
	}

	victim = top;
	set_head(victim, nb | PREV_INUSE);
	top = chunk_at_offset(victim, nb);
	set_head(top, remainder_size | PREV_INUSE);
	return chunk2mem(victim);
}

int strncmp(const char * cs, const char * ct, size_t count) /* <=== strncmp */ 
{
	register signed char __res = 0;

	BUG_ON(!cs || !ct);

	while (count) {
		if ((__res = *cs - *ct++) != 0 || !*cs++)
			break;
		count--;
	}

	return __res;
}

void *malloc(size_t bytes) /* <=== malloc */ 
{
	void *mem;
	/*
	 * tlsf_malloc returns NULL for zero bytes, we instead want
	 * to have a valid pointer.
	 */
	if (!bytes)
		bytes = 1;

	mem = tlsf_malloc(tlsf_mem_pool, bytes);
	if (!mem)
		errno = ENOMEM;

	return mem;
}

static inline int digest_length(struct digest *d) /* <=== digest_length */ 
